5	torch::Tensor single_mha(torch::Tensor& q, torch::Tensor& k, torch::Tensor& v, int head_dim) {
6	    // Optional RoPE
7	    const float sm_scale = 1.f / std::sqrt(float(head_dim));
8	    auto scaled_q = q * sm_scale;
9	    
10	    auto scores = torch::einsum("bthd,bshd->bhts", {scaled_q, k});
11	    auto attention = torch::softmax(scores, -1).to(v.dtype());
12	    auto output = torch::einsum("bhts,bshd->bthd", {attention, v});
13	    return output;
14	}
