5	torch::Tensor single_mha(torch::Tensor& q, torch::Tensor& k, torch::Tensor& v, int head_dim) {
6	    const float sm_scale = 1.f / std::sqrt(float(head_dim));
7	    auto scaled_q = q * sm_scale;
8	    
9	    auto scores = torch::einsum("bthd,bshd->bhts", {scaled_q, k});
10	    auto attention = torch::softmax(scores, -1).to(v.dtype());
11	    auto output = torch::einsum("bhts,bshd->bthd", {attention, v});
12	    return output;
13	}
